// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Browse or search the catalog
	// (GET /anime)
	ListAnime(w http.ResponseWriter, r *http.Request, params ListAnimeParams)
	// Anime detail with episodes
	// (GET /anime/{id})
	GetAnime(w http.ResponseWriter, r *http.Request, id int64)
	// An episode's thread with context (created on first visit)
	// (GET /anime/{id}/episodes/{number}/thread)
	GetEpisodeThread(w http.ResponseWriter, r *http.Request, id int64, number int)
	// Reviews for an anime, most helpful first
	// (GET /anime/{id}/reviews)
	ListAnimeReviews(w http.ResponseWriter, r *http.Request, id int64, params ListAnimeReviewsParams)
	// The caller's review of this anime (404 when none)
	// (GET /anime/{id}/reviews/mine)
	GetMyReview(w http.ResponseWriter, r *http.Request, id int64)
	// Write or edit the caller's review
	// (PUT /anime/{id}/reviews/mine)
	UpsertMyReview(w http.ResponseWriter, r *http.Request, id int64)
	// Discussion index for an anime (series board + episode threads)
	// (GET /anime/{id}/threads)
	GetAnimeThreads(w http.ResponseWriter, r *http.Request, id int64)
	// The anime's series board (created on first visit)
	// (GET /anime/{id}/threads/series)
	GetSeriesThread(w http.ResponseWriter, r *http.Request, id int64)
	// Begin Discord OAuth (redirects to discord.com)
	// (GET /auth/discord)
	DiscordStart(w http.ResponseWriter, r *http.Request)
	// Discord OAuth callback (redirects back to the web app)
	// (GET /auth/discord/callback)
	DiscordCallback(w http.ResponseWriter, r *http.Request, params DiscordCallbackParams)
	// Log in with email + password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Revoke this session family and clear the cookie
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// The authenticated account
	// (GET /auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// Set a new password with a mailed token
	// (POST /auth/password-reset/confirm)
	ConfirmPasswordReset(w http.ResponseWriter, r *http.Request)
	// Send a password-reset link
	// (POST /auth/password-reset/request)
	RequestPasswordReset(w http.ResponseWriter, r *http.Request)
	// Rotate the refresh cookie into a fresh session
	// (POST /auth/refresh)
	RefreshSession(w http.ResponseWriter, r *http.Request)
	// Create an account with email + password
	// (POST /auth/register)
	Register(w http.ResponseWriter, r *http.Request)
	// Send a fresh email-verification link
	// (POST /auth/resend-verification)
	ResendVerification(w http.ResponseWriter, r *http.Request)
	// Confirm an email address with a mailed token
	// (POST /auth/verify-email)
	VerifyEmail(w http.ResponseWriter, r *http.Request)
	// Soft-delete a comment (author or moderator); tombstone remains
	// (DELETE /comments/{commentId})
	DeleteComment(w http.ResponseWriter, r *http.Request, commentId int64)
	// Remove a reaction
	// (DELETE /comments/{commentId}/reactions/{emoji})
	RemoveReaction(w http.ResponseWriter, r *http.Request, commentId int64, emoji Emoji)
	// React to a comment
	// (PUT /comments/{commentId}/reactions/{emoji})
	AddReaction(w http.ResponseWriter, r *http.Request, commentId int64, emoji Emoji)
	// Recent, highly-rated, under-watched titles
	// (GET /hidden-gems)
	GetHiddenGems(w http.ResponseWriter, r *http.Request)
	// Import a public AniList list by username
	// (POST /import/anilist)
	StartAniListImport(w http.ResponseWriter, r *http.Request)
	// Import job status and match preview
	// (GET /import/jobs/{id})
	GetImportJob(w http.ResponseWriter, r *http.Request, id int64)
	// Apply a ready import to the user's list
	// (POST /import/jobs/{id}/commit)
	CommitImportJob(w http.ResponseWriter, r *http.Request, id int64)
	// Import a MyAnimeList XML export (.xml or .xml.gz)
	// (POST /import/mal)
	StartMALImport(w http.ResponseWriter, r *http.Request)
	// The authenticated user's favorites
	// (GET /me/favorites)
	GetMyFavorites(w http.ResponseWriter, r *http.Request)
	// Remove from favorites
	// (DELETE /me/favorites/{animeId})
	RemoveFavorite(w http.ResponseWriter, r *http.Request, animeId int64)
	// Whether this anime is in the user's favorites
	// (GET /me/favorites/{animeId})
	GetFavoriteState(w http.ResponseWriter, r *http.Request, animeId int64)
	// Add to favorites
	// (PUT /me/favorites/{animeId})
	AddFavorite(w http.ResponseWriter, r *http.Request, animeId int64)
	// Activity from everyone the caller follows
	// (GET /me/feed)
	GetMyFeed(w http.ResponseWriter, r *http.Request, params GetMyFeedParams)
	// The authenticated user's anime list
	// (GET /me/list)
	GetMyList(w http.ResponseWriter, r *http.Request, params GetMyListParams)
	// Remove this anime from the user's list
	// (DELETE /me/list/{animeId})
	DeleteMyListEntry(w http.ResponseWriter, r *http.Request, animeId int64)
	// This user's entry for one anime (404 when untracked)
	// (GET /me/list/{animeId})
	GetMyListEntry(w http.ResponseWriter, r *http.Request, animeId int64)
	// Add or update this anime on the user's list
	// (PUT /me/list/{animeId})
	UpsertMyListEntry(w http.ResponseWriter, r *http.Request, animeId int64)
	// The caller's notifications, newest first
	// (GET /me/notifications)
	GetMyNotifications(w http.ResponseWriter, r *http.Request, params GetMyNotificationsParams)
	// Mark notifications read (specific ids or all)
	// (POST /me/notifications/read)
	MarkNotificationsRead(w http.ResponseWriter, r *http.Request)
	// Unread notification count (for the bell)
	// (GET /me/notifications/unread-count)
	GetUnreadCount(w http.ResponseWriter, r *http.Request)
	// Edit bio, avatar, favorite genres, and profile banner
	// (PATCH /me/profile)
	UpdateMyProfile(w http.ResponseWriter, r *http.Request)
	// Taste-based suggestions with explanations
	// (GET /me/recommendations)
	GetMyRecommendations(w http.ResponseWriter, r *http.Request)
	// Open reports queue (moderators only)
	// (GET /mod/reports)
	ListOpenReports(w http.ResponseWriter, r *http.Request, params ListOpenReportsParams)
	// Close a report as resolved or dismissed (moderators only)
	// (POST /mod/reports/{reportId})
	ResolveReport(w http.ResponseWriter, r *http.Request, reportId int64)
	// Report content or a user to the moderators
	// (POST /reports)
	FileReport(w http.ResponseWriter, r *http.Request)
	// Soft-delete a review (author or moderator)
	// (DELETE /reviews/{reviewId})
	DeleteReview(w http.ResponseWriter, r *http.Request, reviewId int64)
	// One review with its anime
	// (GET /reviews/{reviewId})
	GetReview(w http.ResponseWriter, r *http.Request, reviewId int64)
	// Remove a helpful mark
	// (DELETE /reviews/{reviewId}/helpful)
	UnmarkHelpful(w http.ResponseWriter, r *http.Request, reviewId int64)
	// Mark a review helpful
	// (PUT /reviews/{reviewId}/helpful)
	MarkHelpful(w http.ResponseWriter, r *http.Request, reviewId int64)
	// Airing schedule for a time window
	// (GET /schedule)
	GetSchedule(w http.ResponseWriter, r *http.Request, params GetScheduleParams)
	// Seasonal chart
	// (GET /seasons/{year}/{season})
	GetSeason(w http.ResponseWriter, r *http.Request, year int, season Season)
	// Busiest threads right now — recent comments, time-decayed, plus live presence
	// (GET /threads/trending)
	GetTrendingThreads(w http.ResponseWriter, r *http.Request, params GetTrendingThreadsParams)
	// A thread's comments, newest first, keyset-paginated (client builds the tree)
	// (GET /threads/{threadId}/comments)
	ListComments(w http.ResponseWriter, r *http.Request, threadId int64, params ListCommentsParams)
	// Add a comment (optionally anchored to a moment)
	// (POST /threads/{threadId}/comments)
	PostComment(w http.ResponseWriter, r *http.Request, threadId int64)
	// Trending Now — recency-weighted, time-decayed
	// (GET /trending)
	GetTrending(w http.ResponseWriter, r *http.Request, params GetTrendingParams)
	// Public profile with stats and showcases
	// (GET /users/{username})
	GetUserProfile(w http.ResponseWriter, r *http.Request, username string)
	// Unfollow this user
	// (DELETE /users/{username}/follow)
	UnfollowUser(w http.ResponseWriter, r *http.Request, username string)
	// Follow counts and whether the caller follows this user
	// (GET /users/{username}/follow)
	GetFollowState(w http.ResponseWriter, r *http.Request, username string)
	// Follow this user
	// (PUT /users/{username}/follow)
	FollowUser(w http.ResponseWriter, r *http.Request, username string)
	// Who follows this user
	// (GET /users/{username}/followers)
	ListFollowers(w http.ResponseWriter, r *http.Request, username string)
	// Who this user follows
	// (GET /users/{username}/following)
	ListFollowing(w http.ResponseWriter, r *http.Request, username string)
	// One page of a user's list, publicly browsable
	// (GET /users/{username}/list)
	GetUserPublicList(w http.ResponseWriter, r *http.Request, username string, params GetUserPublicListParams)
	// Reviews written by a user, newest first
	// (GET /users/{username}/reviews)
	ListUserReviews(w http.ResponseWriter, r *http.Request, username string, params ListUserReviewsParams)
}

